/* =========================================================
   ASV CONTRACTORS - Bold industrial / architectural redesign
   Brand palette taken from the ASV logo:
   navy #0d2545 · brand blue #2898b8 · gold #f06a1a · white · mist #eef3f8
   ========================================================= */
:root{
  --navy:#0d2545; --navy-2:#123056; --navy-3:#0a1c37;
  --blue:#2898b8; --blue-d:#207f97; --blue-050:#e7f3f6;
  --gold:#f06a1a; --gold-2:#f8863a; --gold-d:#c05313;
  --ink:#14243d; --body:#48566b; --muted:#8592a6;
  --mist:#eef3f8; --mist-2:#f6f9fc; --line:#dbe3ee; --line-ink:rgba(255,255,255,.14);
  --white:#fff;
  --max:1300px; --gut:40px;
  --disp:"Oswald",Impact,"Arial Narrow",sans-serif;
  --f:"Inter",-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;font-family:var(--f);color:var(--body);background:var(--white);line-height:1.7;-webkit-font-smoothing:antialiased;overflow-x:hidden}
a{text-decoration:none;color:inherit}
img{max-width:100%;display:block}
h1,h2,h3,h4{margin:0;color:var(--ink);font-family:var(--disp);font-weight:600;line-height:1.02;text-transform:uppercase;letter-spacing:.005em}
p{margin:0}
.wrap{max-width:var(--max);margin:0 auto;padding:0 var(--gut)}
.ic{width:1em;height:1em;flex:none;stroke:currentColor;fill:none;stroke-width:1.7;stroke-linecap:square;stroke-linejoin:miter}
.olabel{display:inline-flex;align-items:center;gap:14px;font-family:var(--f);font-size:.72rem;font-weight:700;letter-spacing:.28em;text-transform:uppercase;color:var(--ink)}
.olabel .num{color:var(--gold-d);font-variant-numeric:tabular-nums;font-family:var(--disp);font-size:1rem}
.olabel .bar{width:40px;height:2px;background:var(--gold)}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:12px;font-family:var(--f);font-weight:700;font-size:.78rem;letter-spacing:.16em;text-transform:uppercase;padding:17px 32px;border:2px solid var(--navy);color:var(--navy);background:transparent;cursor:pointer;transition:.22s;position:relative;overflow:hidden;isolation:isolate}
.btn>*{position:relative;z-index:1}
.btn::before{content:"";position:absolute;inset:0;background:var(--navy);transform:translateY(101%);transition:.28s;z-index:-1}
.btn:hover::before{transform:translateY(0)}
.btn:hover{color:#fff;border-color:var(--navy)}
.btn-gold{border-color:var(--gold);color:var(--navy);background:var(--gold)}
.btn-gold::before{background:var(--gold-d)}
.btn-gold:hover{color:#fff;border-color:var(--gold-d)}
.btn-blue{border-color:var(--blue);color:#fff;background:var(--blue)}
.btn-blue::before{background:var(--blue-d)}
.btn-blue:hover{color:#fff;border-color:var(--blue-d)}
.btn-light{border-color:rgba(255,255,255,.7);color:#fff}
.btn-light::before{background:#fff}
.btn-light:hover{color:var(--navy);border-color:#fff}
.btn .ic{width:15px;height:15px;stroke-width:2.4}
.section{padding:120px 0;position:relative}
.rv{opacity:1;transform:none}
html.reveal .rv{opacity:0;transform:translateY(34px);transition:opacity .7s cubic-bezier(.2,.7,.2,1),transform .7s cubic-bezier(.2,.7,.2,1)}
html.reveal .rv.in{opacity:1;transform:none}
.rv.in{opacity:1;transform:none}
.rv.d1{transition-delay:.08s}.rv.d2{transition-delay:.16s}.rv.d3{transition-delay:.24s}
.wm{position:absolute;font-family:var(--disp);font-weight:700;font-size:22rem;line-height:.7;color:var(--navy);opacity:.045;pointer-events:none;z-index:0;letter-spacing:-.04em}

/* ============ TOP BAR ============ */
.topbar{background:var(--navy);color:#c3d0e2;font-size:.74rem;letter-spacing:.08em;position:relative;z-index:40}
.topbar .wrap{display:flex;align-items:center;justify-content:space-between;min-height:42px;gap:16px}
.topbar .tb-l{display:flex;gap:26px;text-transform:uppercase}
.topbar .tb-l span{display:inline-flex;align-items:center;gap:9px}
.topbar .ic{width:14px;height:14px;color:var(--gold);stroke-width:2.4}
.topbar a{color:#fff;font-weight:700}
.topbar a:hover{color:var(--gold)}
@media(max-width:820px){.topbar .tb-l span.hide-sm{display:none}}

/* ============ HEADER ============ */
.hdr{position:absolute;top:0;left:0;right:0;z-index:60}
.hdr.solid{position:fixed;top:0;background:rgba(13,37,69,.96);backdrop-filter:blur(10px);border-bottom:3px solid var(--gold);animation:drop .35s ease}
@keyframes drop{from{transform:translateY(-100%)}to{transform:none}}
.hdr-in{display:flex;align-items:center;gap:30px;min-height:96px}
.brand{flex:none;display:flex;align-items:center}
.brand img{height:78px;width:auto}
.nav-cb{display:none}
.nav{margin-left:auto;display:flex;align-items:center;gap:38px}
.nav-links{display:flex;align-items:center;gap:30px;list-style:none;margin:0;padding:0}
.nav-links a{font-family:var(--f);font-size:.8rem;font-weight:700;letter-spacing:.13em;text-transform:uppercase;color:#fff;position:relative;padding:8px 0}
.nav-links a::after{content:"";position:absolute;left:0;bottom:0;width:0;height:2px;background:var(--gold);transition:.28s}
.nav-links a:hover::after{width:100%}
.hdr-cta{display:flex;align-items:center;gap:14px;flex:none}
.hdr-cta .call{display:inline-flex;align-items:center;gap:9px;font-family:var(--f);font-size:.8rem;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:#fff;border:2px solid rgba(255,255,255,.5);padding:13px 22px;transition:.2s}
.hdr-cta .call:hover{background:#fff;color:var(--navy)}
.hdr-cta .quote{background:var(--gold);color:var(--navy);padding:15px 26px;font-family:var(--f);font-size:.8rem;font-weight:700;letter-spacing:.12em;text-transform:uppercase;transition:.2s;clip-path:polygon(10px 0,100% 0,100% calc(100% - 10px),calc(100% - 10px) 100%,0 100%,0 10px)}
.hdr-cta .quote:hover{background:#fff}
.burger{display:none;margin-left:auto;width:50px;height:50px;border:2px solid rgba(255,255,255,.5);align-items:center;justify-content:center;color:#fff;cursor:pointer;background:transparent}
.burger svg{width:22px;height:22px;stroke-width:2.4}
.burger .x{display:none}
.nav-cb:checked ~ .burger .menu{display:none}.nav-cb:checked ~ .burger .x{display:block}
@media(max-width:1120px){
  .burger{display:flex}
  .nav{position:fixed;inset:0 0 0 auto;top:0;height:100vh;width:min(370px,88vw);margin:0;background:var(--navy);flex-direction:column;align-items:stretch;gap:0;padding:96px 0 30px;transform:translateX(105%);transition:transform .32s ease;overflow-y:auto;z-index:80;border-left:3px solid var(--gold)}
  .nav-cb:checked ~ .nav{transform:translateX(0)}
  .nav-links{flex-direction:column;align-items:stretch;gap:0;width:100%}
  .nav-links a{color:#fff;padding:20px 32px;border-bottom:1px solid var(--line-ink);letter-spacing:.16em;font-size:1.02rem;font-family:var(--disp);font-weight:500}
  .nav-links a::after{display:none}
  .nav-links a:hover{background:var(--navy-2);color:var(--gold);padding-left:40px}
  .hdr-cta{display:none}
  .nav .m-cta{display:flex;flex-direction:column;margin-top:auto}
  .nav .m-cta a{padding:20px 32px;text-align:center;font-size:.85rem;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;font-family:var(--f)}
  .nav .m-cta .mc-call{border-top:1px solid var(--line-ink);border-bottom:1px solid var(--line-ink)}
  .nav .m-cta .mc-quote{background:var(--gold);color:var(--navy)}
}
@media(min-width:1121px){.nav .m-cta{display:none}}
.scrim{display:none}
@media(max-width:1120px){.nav-cb:checked ~ .scrim{display:block;position:fixed;inset:0;background:rgba(10,20,40,.55);z-index:75}}

/* ============ HERO ============ */
.hero{position:relative;min-height:100vh;display:flex;align-items:center;background:var(--navy-3);overflow:hidden}
.hero-bg{position:absolute;inset:0}
.hero-bg img{width:100%;height:100%;object-fit:cover;opacity:.55;transform:scale(1.08);animation:kb 18s ease-out forwards}
@keyframes kb{to{transform:scale(1)}}
.hero-bg::after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(10,24,45,.94) 0%,rgba(10,24,45,.66) 42%,rgba(10,24,45,.3) 100%),linear-gradient(180deg,transparent 52%,rgba(10,24,45,.88) 100%)}
.hero-grain{position:absolute;inset:0;opacity:.5;pointer-events:none;background-image:linear-gradient(rgba(255,255,255,.03) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.03) 1px,transparent 1px);background-size:52px 52px;z-index:2}
.hero-inner{position:relative;z-index:4;width:100%;padding:150px 0 0}
.hero-kicker{display:inline-flex;align-items:center;gap:14px;color:#fff;font-size:.76rem;font-weight:700;letter-spacing:.26em;text-transform:uppercase;margin-bottom:26px}
.hero-kicker::before{content:"";width:46px;height:2px;background:var(--gold)}
.hero h1{color:#fff;font-family:var(--disp);font-weight:700;font-size:clamp(3.2rem,10vw,9rem);line-height:.92;letter-spacing:-.01em;text-transform:uppercase}
.hero h1 .out{-webkit-text-stroke:2px rgba(255,255,255,.55);color:transparent;display:inline-block}
.hero h1 .amp{color:var(--gold)}
.hero-tag{margin-top:30px;color:#d3ddec;font-size:1.1rem;max-width:46ch;font-family:var(--f);border-left:3px solid var(--gold);padding-left:20px}
.hero-cta{display:flex;flex-wrap:wrap;gap:16px;margin-top:38px}
.hero-stats{position:relative;z-index:4;margin-top:70px;border-top:1px solid rgba(255,255,255,.16)}
.hero-stats .wrap{display:grid;grid-template-columns:repeat(4,1fr)}
.hstat{padding:26px 30px 34px;border-right:1px solid rgba(255,255,255,.12)}
.hstat:last-child{border-right:0}
.hstat b{font-family:var(--disp);font-weight:700;font-size:2.7rem;color:#fff;line-height:1;display:block}
.hstat b span{color:var(--gold)}
.hstat small{color:#9fb0c6;font-size:.72rem;letter-spacing:.16em;text-transform:uppercase;font-weight:600;margin-top:8px;display:block}
.hero-scroll{position:absolute;right:var(--gut);bottom:150px;z-index:4;writing-mode:vertical-rl;color:rgba(255,255,255,.6);font-size:.68rem;letter-spacing:.3em;text-transform:uppercase;display:flex;align-items:center;gap:14px}
.hero-scroll::after{content:"";width:1px;height:60px;background:linear-gradient(var(--gold),transparent)}
@media(max-width:900px){.hero-inner{padding-top:130px}.hero-stats .wrap{grid-template-columns:1fr 1fr}.hstat{border-bottom:1px solid rgba(255,255,255,.12)}.hstat:nth-child(2){border-right:0}.hero-scroll{display:none}}
@media(max-width:520px){.hstat b{font-size:2rem}}

/* ============ MARQUEE ============ */
.marquee{background:var(--navy);color:#fff;overflow:hidden;padding:20px 0;position:relative;z-index:5;border-top:3px solid var(--gold)}
.marquee-track{display:flex;width:max-content;animation:scroll 26s linear infinite}
.marquee:hover .marquee-track{animation-play-state:paused}
.marquee span{font-family:var(--disp);font-weight:600;font-size:1.5rem;text-transform:uppercase;letter-spacing:.04em;padding:0 34px;display:inline-flex;align-items:center;gap:34px;white-space:nowrap}
.marquee span::after{content:"◆";font-size:.7rem;color:var(--gold)}
@keyframes scroll{to{transform:translateX(-50%)}}

/* ============ OVERVIEW ============ */
.overview{background:var(--white);overflow:hidden}
.ov-grid{display:grid;grid-template-columns:1.05fr .95fr;gap:80px;align-items:center;position:relative;z-index:1}
.ov-copy h2{font-size:clamp(2rem,3.6vw,3rem);margin:26px 0 26px;line-height:1.04}
.ov-copy h2 em{font-style:normal;color:var(--blue)}
.ov-copy p{margin-bottom:18px;font-size:1.03rem}
.ov-copy .btn{margin-top:20px}
.ov-fig{position:relative}
.ov-fig .imgwrap{overflow:hidden;position:relative}
.ov-fig img{width:100%;aspect-ratio:4/5;object-fit:cover;transition:.6s}
.ov-fig:hover img{transform:scale(1.05)}
.ov-fig .tab{position:absolute;left:-1px;bottom:-1px;background:var(--gold);color:var(--navy);padding:24px 30px;max-width:230px;clip-path:polygon(0 0,100% 0,100% 100%,20px 100%,0 calc(100% - 20px))}
.ov-fig .tab b{font-family:var(--disp);display:block;font-size:2.7rem;font-weight:700;line-height:1}
.ov-fig .tab small{font-size:.72rem;letter-spacing:.18em;text-transform:uppercase;opacity:.92;margin-top:6px;display:block;font-weight:700}
.ov-fig::before{content:"";position:absolute;top:-20px;right:-20px;width:130px;height:130px;border:3px solid var(--blue);z-index:-1}
@media(max-width:900px){.ov-grid{grid-template-columns:1fr;gap:48px}.ov-fig{order:-1}}

/* ============ SERVICES ============ */
.services{background:var(--navy);color:#fff;overflow:hidden}
.services .olabel{color:#fff}
.svc-head{display:grid;grid-template-columns:1fr 1fr;gap:40px;align-items:end;margin-bottom:56px;position:relative;z-index:1}
.svc-head h2{color:#fff;font-size:clamp(2rem,4vw,3.2rem);margin-top:22px}
.svc-head p{font-size:1.06rem;color:#c1cede;font-family:var(--f)}
.svc-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.12)}
.svc{position:relative;min-height:440px;overflow:hidden;background:var(--navy-2);display:flex;flex-direction:column;justify-content:flex-end}
.svc img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;filter:brightness(.5);transition:.55s}
.svc:hover img{filter:brightness(.7);transform:scale(1.08)}
.svc::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(13,37,69,.1) 30%,rgba(10,24,45,.92) 100%)}
.svc .bignum{position:absolute;top:22px;left:24px;z-index:2;font-family:var(--disp);font-weight:700;font-size:3.4rem;color:rgba(255,255,255,.22);line-height:1;transition:.35s}
.svc:hover .bignum{color:var(--gold)}
.svc .svc-body{position:relative;z-index:2;padding:30px 26px}
.svc h3{color:#fff;font-size:1.4rem;font-weight:600;line-height:1.05}
.svc .go{display:flex;align-items:center;gap:10px;margin-top:14px;color:#fff;font-family:var(--f);font-size:.72rem;font-weight:700;letter-spacing:.16em;text-transform:uppercase;max-height:0;opacity:0;overflow:hidden;transition:.4s}
.svc:hover .go{max-height:40px;opacity:1}
.svc .go .ic{width:15px;height:15px;stroke-width:2.6;color:var(--gold)}
.svc .rbar{position:absolute;left:0;bottom:0;height:5px;width:0;background:var(--gold);z-index:3;transition:.4s}
.svc:hover .rbar{width:100%}
.svc-foot{display:flex;align-items:center;justify-content:space-between;gap:22px;margin-top:48px;flex-wrap:wrap;border-top:1px solid rgba(255,255,255,.14);padding-top:34px}
.svc-foot span{font-family:var(--disp);font-size:1.5rem;color:#fff;text-transform:uppercase;font-weight:500}
@media(max-width:960px){.svc-grid{grid-template-columns:1fr 1fr}.svc-head{grid-template-columns:1fr;gap:18px}}
@media(max-width:520px){.svc-grid{grid-template-columns:1fr}.svc{min-height:340px}}

/* ============ GOVERNMENT ============ */
.gov{background:var(--mist);overflow:hidden}
.gov-grid{display:grid;grid-template-columns:.95fr 1.05fr;gap:70px;align-items:center;position:relative;z-index:1}
.gov-fig{position:relative}
.gov-fig .main{width:100%;aspect-ratio:4/3;object-fit:cover}
.gov-fig .inset{position:absolute;right:-24px;bottom:-30px;width:44%;aspect-ratio:1/1;object-fit:cover;border:6px solid var(--mist);box-shadow:0 20px 40px rgba(13,37,69,.2)}
.gov-fig .flag{position:absolute;top:0;left:0;background:var(--blue);color:#fff;font-family:var(--f);font-size:.68rem;font-weight:700;letter-spacing:.16em;text-transform:uppercase;padding:10px 16px;z-index:2}
.gov-copy h2{font-size:clamp(1.9rem,3.6vw,2.9rem);margin:22px 0 20px;line-height:1.04}
.gov-copy h2 em{font-style:normal;color:var(--blue)}
.gov-copy .lead{font-size:1.05rem;color:var(--ink);margin-bottom:26px;font-family:var(--f)}
.gov-check{list-style:none;margin:0 0 30px;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:14px 24px}
.gov-check li{display:flex;gap:12px;font-size:.96rem;color:var(--ink);font-weight:500;font-family:var(--f)}
.gov-check .ic{width:22px;height:22px;color:#fff;background:var(--blue);border-radius:2px;padding:3px;flex:none;stroke-width:3}
.gov-actions{display:flex;gap:14px;flex-wrap:wrap}
.gov-proof{margin-top:30px;padding-top:24px;border-top:1px solid var(--line);display:flex;align-items:center;gap:18px;flex-wrap:wrap}
.gov-proof .pl{font-family:var(--f);font-size:.7rem;font-weight:700;letter-spacing:.16em;text-transform:uppercase;color:var(--muted)}
.gov-proof .chip{font-family:var(--disp);font-weight:500;text-transform:uppercase;font-size:.95rem;color:var(--navy);background:#fff;border:1px solid var(--line);padding:8px 15px}
.gov-proof .chip b{color:var(--blue)}
@media(max-width:900px){.gov-grid{grid-template-columns:1fr;gap:56px}.gov-check{grid-template-columns:1fr}.gov-fig .inset{width:40%}}

/* compliance strip */
.compliance{background:var(--navy-3);color:#fff}
.compliance .wrap{display:flex;flex-wrap:wrap;justify-content:space-between;gap:24px 30px;padding:34px var(--gut)}
.compliance .ci{display:flex;align-items:center;gap:14px}
.compliance .ci .ic{width:26px;height:26px;color:var(--gold);stroke-width:2}
.compliance .ci b{font-family:var(--disp);font-weight:500;text-transform:uppercase;font-size:1.05rem;color:#fff;letter-spacing:.02em}
.compliance .ci small{display:block;color:#9fb0c6;font-size:.74rem;font-family:var(--f);letter-spacing:.04em}

/* ============ PROJECTS ============ */
.projects{background:var(--white);overflow:hidden}
.pj-head{display:flex;align-items:flex-end;justify-content:space-between;gap:30px;margin-bottom:56px;position:relative;z-index:1}
.pj-head h2{font-size:clamp(2rem,4vw,3.2rem);margin-top:22px}
.pj-grid{display:grid;grid-template-columns:1fr 1fr;gap:26px;position:relative;z-index:1}
.pj{background:#fff;overflow:hidden;position:relative;display:flex;flex-direction:column;border:1px solid var(--line);transition:.3s}
.pj:hover{transform:translateY(-8px);box-shadow:0 30px 60px rgba(13,37,69,.16);border-color:transparent}
.pj-img{position:relative;aspect-ratio:16/9;overflow:hidden}
.pj-img img{width:100%;height:100%;object-fit:cover;transition:.55s}
.pj:hover .pj-img img{transform:scale(1.07)}
.pj-img .idx{position:absolute;top:0;left:0;background:var(--navy);color:#fff;font-family:var(--disp);font-size:1.05rem;font-weight:700;letter-spacing:.12em;padding:8px 18px}
.pj-img .tag{position:absolute;bottom:14px;right:14px;background:var(--gold);color:var(--navy);font-family:var(--f);font-size:.66rem;letter-spacing:.14em;text-transform:uppercase;font-weight:700;padding:7px 12px}
.pj-body{padding:32px 32px 34px}
.pj-body h3{font-size:1.7rem;font-weight:600}
.pj-scope{margin-top:16px}
.pj-scope .sl{font-family:var(--f);font-size:.68rem;letter-spacing:.2em;text-transform:uppercase;color:var(--muted);font-weight:700}
.pj-scope ul{list-style:none;margin:12px 0 0;padding:0;display:grid;gap:10px}
.pj-scope li{display:flex;gap:13px;font-size:.98rem;color:var(--body)}
.pj-scope li::before{content:"";width:8px;height:8px;background:var(--gold);flex:none;margin-top:8px;transform:rotate(45deg)}
.pj-body .plink{display:inline-flex;align-items:center;gap:11px;margin-top:24px;font-family:var(--f);font-size:.72rem;letter-spacing:.16em;text-transform:uppercase;font-weight:700;color:var(--navy);border-bottom:2px solid var(--gold);padding-bottom:6px}
.pj-body .plink .ic{width:15px;height:15px;stroke-width:2.6;transition:.2s}
.pj-body .plink:hover .ic{transform:translateX(6px)}
@media(max-width:820px){.pj-grid{grid-template-columns:1fr}.pj-head{flex-direction:column;align-items:flex-start}}

/* ============ TESTIMONIALS ============ */
.testi{background:var(--navy);color:#fff;position:relative;overflow:hidden}
.testi .wm{color:#fff}
.testi .olabel{color:#fff}
.testi-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.12);margin-top:56px;position:relative;z-index:2}
.tcard{background:var(--navy);padding:42px 34px;display:flex;flex-direction:column;transition:.3s;position:relative}
.tcard::before{content:"“";position:absolute;top:16px;right:24px;font-family:Georgia,serif;font-size:5rem;color:var(--gold);opacity:.5;line-height:1}
.tcard:hover{background:var(--navy-2)}
.tcard .stars{display:flex;gap:4px;color:var(--gold);margin-bottom:22px}
.tcard .stars .ic{width:17px;height:17px;fill:currentColor;stroke:none}
.tcard p{color:#d3ddec;font-size:.99rem;line-height:1.78;flex:1;font-family:var(--f)}
.tcard .by{margin-top:28px;padding-top:24px;border-top:1px solid rgba(255,255,255,.14)}
.tcard .by b{font-family:var(--disp);color:#fff;font-size:1.25rem;font-weight:600;display:block;letter-spacing:.01em}
.tcard .by small{color:#9fb0c6;font-size:.82rem;font-family:var(--f)}
@media(max-width:900px){.testi-grid{grid-template-columns:1fr}}

/* ============ CONTACT ============ */
.contact{background:var(--mist);overflow:hidden}
.ct-grid{display:grid;grid-template-columns:1.05fr .95fr;gap:70px;align-items:center;position:relative;z-index:1}
.ct-copy h2{font-size:clamp(2.2rem,4.4vw,3.6rem);margin:24px 0 22px;line-height:1}
.ct-copy h2 em{font-style:normal;color:var(--blue)}
.ct-copy p{font-size:1.05rem;color:var(--ink);margin-bottom:18px;max-width:46ch;font-family:var(--f)}
.ct-actions{display:flex;gap:14px;flex-wrap:wrap;margin-top:30px}
.ct-lines{margin-top:38px;display:grid;gap:1px;background:var(--line);border:1px solid var(--line)}
.ct-lines a{background:#fff;display:flex;align-items:center;gap:16px;padding:20px 24px;font-size:1.05rem;color:var(--navy);font-family:var(--disp);font-weight:500;transition:.2s}
.ct-lines a:hover{background:var(--blue-050);padding-left:32px}
.ct-lines .ic{width:20px;height:20px;color:var(--blue);stroke-width:1.9}
.ct-mosaic{display:grid;grid-template-columns:1fr 1fr;grid-template-rows:200px 200px 200px;gap:6px}
.ct-mosaic .im{overflow:hidden}
.ct-mosaic img{width:100%;height:100%;object-fit:cover;transition:.5s}
.ct-mosaic .im:hover img{transform:scale(1.06)}
.ct-mosaic .big{grid-row:span 2}
@media(max-width:900px){.ct-grid{grid-template-columns:1fr;gap:44px}.ct-mosaic{grid-template-rows:150px 150px 150px}}

/* email capture */
.emailcap{background:var(--blue);color:#fff;position:relative;overflow:hidden}
.emailcap::before{content:"";position:absolute;top:0;right:0;width:40%;height:100%;background:repeating-linear-gradient(45deg,rgba(255,255,255,.07) 0 14px,transparent 14px 28px)}
.emailcap .wrap{display:grid;grid-template-columns:1fr auto;gap:40px;align-items:center;padding:60px var(--gut);position:relative;z-index:1}
.emailcap h2{color:#fff;font-size:clamp(1.6rem,3vw,2.4rem)}
.ec-form{display:flex;min-width:min(480px,82vw);box-shadow:0 20px 40px rgba(0,0,0,.2)}
.ec-form input{flex:1;border:0;background:#fff;color:var(--ink);padding:20px 22px;font:inherit;font-size:.98rem;outline:none}
.ec-form button{border:0;background:var(--gold);color:var(--navy);padding:0 38px;font-family:var(--f);font-size:.8rem;font-weight:700;letter-spacing:.16em;text-transform:uppercase;cursor:pointer;transition:.2s}
.ec-form button:hover{background:var(--navy);color:#fff}
@media(max-width:820px){.emailcap .wrap{grid-template-columns:1fr;gap:22px}.ec-form{min-width:0}}

/* ============ FOOTER ============ */
footer.site{background:var(--navy-3);color:rgba(255,255,255,.6);padding:80px 0 30px}
.foot-top{display:grid;grid-template-columns:1.6fr 1fr 1fr;gap:48px;padding-bottom:46px;border-bottom:1px solid var(--line-ink)}
.foot-brand img{height:88px;width:auto;margin-bottom:24px}
.foot-brand p{font-size:.95rem;max-width:42ch;color:rgba(255,255,255,.55);font-family:var(--f)}
.foot-brand .fcontact{margin-top:24px;display:grid;gap:12px}
.foot-brand .fcontact a{display:inline-flex;align-items:center;gap:12px;font-size:1.05rem;color:#eaeef4;font-family:var(--disp);font-weight:500}
.foot-brand .fcontact a:hover{color:var(--gold)}
.foot-brand .fcontact .ic{width:18px;height:18px;color:var(--gold);stroke-width:1.9}
footer.site h4{color:#fff;font-family:var(--f);font-size:.74rem;letter-spacing:.22em;text-transform:uppercase;font-weight:700;margin:0 0 22px}
footer.site .fcol ul{list-style:none;margin:0;padding:0;display:grid;gap:14px}
footer.site .fcol a{font-size:.95rem;letter-spacing:.02em;font-family:var(--f);color:rgba(255,255,255,.6)}
footer.site .fcol a:hover{color:var(--gold);padding-left:5px;transition:.2s}
.foot-bottom{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;padding-top:28px;font-size:.82rem;color:rgba(255,255,255,.42);letter-spacing:.04em;font-family:var(--f)}
.foot-bottom .legal{display:flex;gap:22px;flex-wrap:wrap}
.foot-credit{text-align:center;margin-top:18px;padding-top:16px;border-top:1px solid var(--line-ink);font-family:var(--f);font-size:.8rem;letter-spacing:.04em;color:rgba(255,255,255,.4)}
@media(max-width:820px){.foot-top{grid-template-columns:1fr;gap:36px}.foot-bottom{flex-direction:column;text-align:center;justify-content:center}.foot-bottom .legal{justify-content:center}}

/* sticky mobile call bar */
.callbar{display:none}
@media(max-width:720px){
  .callbar{display:grid;grid-template-columns:1fr 1fr;position:fixed;left:0;right:0;bottom:0;z-index:90}
  .callbar a{padding:17px;text-align:center;font-family:var(--f);font-weight:700;font-size:.78rem;letter-spacing:.14em;text-transform:uppercase;display:flex;align-items:center;justify-content:center;gap:9px}
  .callbar .c1{background:var(--gold);color:var(--navy)}.callbar .c2{background:var(--navy);color:#fff}
  .callbar .ic{width:16px;height:16px;stroke-width:2.4}
  body{padding-bottom:55px}
}
.totop{position:fixed;right:24px;bottom:26px;width:48px;height:48px;background:var(--navy);color:#fff;display:grid;place-items:center;z-index:50;border:2px solid var(--gold);transition:.2s}
.totop:hover{background:var(--gold);color:var(--navy);transform:translateY(-3px)}
.totop .ic{width:20px;height:20px;stroke-width:2.6}
@media(max-width:720px){.totop{bottom:72px}}
.demonote{background:var(--navy-3);color:#aeb9cb;font-size:.78rem;text-align:center;padding:9px 16px;letter-spacing:.04em;font-family:var(--f)}
.demonote b{color:#fff}

/* ===== SUBPAGE ADDITIONS ===== */
.page-hero{position:relative;background:var(--navy-3);overflow:hidden;display:flex;align-items:flex-end;min-height:clamp(420px,58vh,580px)}
.page-hero .pbg{position:absolute;inset:0}
.page-hero .pbg img{width:100%;height:100%;object-fit:cover;opacity:.5}
.page-hero .pbg::after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(10,24,45,.92),rgba(10,24,45,.5) 65%,rgba(10,24,45,.32)),linear-gradient(180deg,rgba(10,24,45,.4),transparent 28%,rgba(10,24,45,.92))}
.page-hero .wrap{position:relative;z-index:3;padding:150px 0 58px;width:100%}
.page-hero .crumb{display:inline-flex;align-items:center;gap:10px;color:#cfe0ea;font-family:var(--f);font-size:.72rem;font-weight:700;letter-spacing:.2em;text-transform:uppercase;margin-bottom:20px}
.page-hero .crumb a:hover{color:var(--gold)}.page-hero .crumb .sep{color:var(--gold)}
.page-hero h1{color:#fff;font-size:clamp(2.4rem,6vw,4.4rem);line-height:.98;letter-spacing:-.01em}
.page-hero .ph-tag{margin-top:22px;color:#d3ddec;font-size:1.1rem;max-width:60ch;font-family:var(--f);border-left:3px solid var(--gold);padding-left:20px}
@media(max-width:900px){.page-hero .wrap{padding-top:130px}}
.pintro{max-width:780px;margin:0 auto 58px}
.pintro.center{text-align:center}.olabel.center{justify-content:center}
.pintro h2{font-size:clamp(2rem,3.8vw,3rem);margin:16px 0 18px;line-height:1.05}
.pintro h2 em{font-style:normal;color:var(--blue)}
.pintro p{font-size:1.08rem}
.split{display:grid;grid-template-columns:1.02fr .98fr;gap:70px;align-items:center;position:relative;z-index:1}
.split + .split{margin-top:96px}
.split .sp-copy h2{font-size:clamp(1.8rem,3.2vw,2.6rem);margin:14px 0 20px;line-height:1.06}
.split .sp-copy h2 em{font-style:normal;color:var(--blue)}
.split .sp-copy p{margin-bottom:16px;font-size:1.03rem}
.sp-fig{position:relative}
.sp-fig img{width:100%;aspect-ratio:4/3;object-fit:cover}
.sp-fig::before{content:"";position:absolute;top:-18px;left:-18px;width:120px;height:120px;border:3px solid var(--gold);z-index:-1}
.split.rev .sp-fig{order:-1}.split.rev .sp-fig::before{left:auto;right:-18px}
@media(max-width:900px){.split{grid-template-columns:1fr;gap:40px}.split.rev .sp-fig{order:0}.split + .split{margin-top:64px}}
.feat{list-style:none;margin:24px 0 0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:15px 26px}
.feat li{display:flex;gap:12px;font-size:1rem;color:var(--ink);font-weight:500;font-family:var(--f)}
.feat .ic{width:22px;height:22px;color:#fff;background:var(--blue);border-radius:2px;padding:3px;flex:none;stroke-width:3}
@media(max-width:620px){.feat{grid-template-columns:1fr}}
.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}
.card{background:#fff;border:1px solid var(--line);padding:38px 32px 34px;transition:.3s;position:relative;overflow:hidden}
.card:hover{transform:translateY(-6px);box-shadow:0 24px 50px rgba(13,37,69,.14);border-color:transparent}
.card .cn{font-family:var(--disp);font-weight:700;font-size:2.2rem;color:var(--blue);line-height:1;opacity:.85}
.card h3{font-size:1.35rem;margin:12px 0 12px}
.card p{font-size:.97rem}
.card .cbar{position:absolute;left:0;top:0;width:5px;height:0;background:var(--gold);transition:.35s}
.card:hover .cbar{height:100%}
@media(max-width:900px){.cards{grid-template-columns:1fr}}
.gal{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
.gal .g{overflow:hidden;aspect-ratio:4/3;position:relative;background:var(--navy-2)}
.gal .g img{width:100%;height:100%;object-fit:cover;transition:.5s}
.gal .g:hover img{transform:scale(1.06)}
@media(max-width:760px){.gal{grid-template-columns:1fr 1fr}}
.pjg{display:grid;grid-template-columns:repeat(3,1fr);gap:26px;position:relative;z-index:1}
@media(max-width:900px){.pjg{grid-template-columns:1fr 1fr}}
@media(max-width:620px){.pjg{grid-template-columns:1fr}}
.svc-grid a.svc{cursor:pointer}
/* CTA enquiry band */
.cta-enq{background:var(--navy);color:#fff;position:relative;overflow:hidden}
.cta-enq::before{content:"";position:absolute;top:0;right:0;width:40%;height:100%;background:repeating-linear-gradient(45deg,rgba(255,255,255,.05) 0 14px,transparent 14px 28px)}
.cta-enq .wrap{display:grid;grid-template-columns:1fr 1.05fr;gap:60px;align-items:center;padding:84px var(--gut);position:relative;z-index:1}
.cta-enq .ce-copy h2{color:#fff;font-size:clamp(2rem,3.6vw,2.9rem);line-height:1.05;margin:14px 0 0}
.cta-enq .ce-copy h2 em{font-style:normal;color:var(--gold)}
.cta-enq .ce-copy p{color:#c1cede;font-size:1.05rem;margin-top:18px;font-family:var(--f);max-width:46ch}
.cta-enq .ce-call{display:inline-flex;align-items:center;gap:12px;margin-top:26px;font-family:var(--disp);font-weight:500;font-size:1.7rem;color:#fff}
.cta-enq .ce-call .ic{width:24px;height:24px;color:var(--gold);stroke-width:2}
.cta-enq .olabel{color:#fff}
@media(max-width:900px){.cta-enq .wrap{grid-template-columns:1fr;gap:34px;padding:60px var(--gut)}}
/* enquiry form */
.enq{background:#fff;padding:34px 30px 30px;box-shadow:0 26px 60px rgba(0,0,0,.24)}
.enq .fh{font-family:var(--disp);font-weight:700;text-transform:uppercase;color:var(--ink);font-size:1.35rem;margin-bottom:6px;letter-spacing:.01em}
.enq .fsub{font-family:var(--f);font-size:.9rem;color:var(--muted);margin-bottom:18px}
.enq form{display:grid;gap:13px}
.enq .frow{display:grid;grid-template-columns:1fr 1fr;gap:13px}
.enq input,.enq select,.enq textarea{width:100%;border:1.5px solid var(--line);background:var(--mist-2);padding:15px 16px;font:inherit;font-size:.97rem;color:var(--ink);outline:none;transition:.2s}
.enq input::placeholder,.enq textarea::placeholder{color:#9aa6b6}
.enq select{color:var(--ink)}
.enq input:focus,.enq select:focus,.enq textarea:focus{border-color:var(--blue);background:#fff}
.enq textarea{resize:vertical;min-height:98px}
.enq button{border:0;background:var(--gold);color:var(--navy);padding:18px 20px;font-family:var(--f);font-weight:700;font-size:.82rem;letter-spacing:.16em;text-transform:uppercase;cursor:pointer;transition:.2s;margin-top:4px}
.enq button:hover{background:var(--navy);color:#fff}
.enq .fnote{font-size:.76rem;color:var(--muted);font-family:var(--f);margin-top:10px}
@media(max-width:560px){.enq .frow{grid-template-columns:1fr}}
/* offices */
.offices{display:grid;grid-template-columns:1fr 1fr;gap:24px}
.office{background:#fff;border:1px solid var(--line);padding:32px 30px;position:relative;transition:.3s}
.office:hover{box-shadow:0 20px 44px rgba(13,37,69,.12);transform:translateY(-4px)}
.office .otag{display:inline-flex;align-items:center;gap:9px;font-family:var(--f);font-size:.68rem;font-weight:700;letter-spacing:.18em;text-transform:uppercase;color:var(--blue);margin-bottom:12px}
.office .otag .ic{width:16px;height:16px;stroke-width:2.4}
.office h3{font-size:1.4rem;margin-bottom:10px}
.office .oaddr{font-family:var(--f);font-size:1.04rem;color:var(--body);line-height:1.7}
@media(max-width:700px){.offices{grid-template-columns:1fr}}
.ct-offices{margin-top:30px;padding-top:26px;border-top:1px solid var(--line);display:grid;grid-template-columns:1fr 1fr;gap:20px}
.ct-offices .cto b{font-family:var(--disp);font-weight:600;text-transform:uppercase;color:var(--navy);font-size:1.05rem;display:block;margin-bottom:5px}
.ct-offices .cto span{font-family:var(--f);font-size:.96rem;color:var(--body);line-height:1.55}
@media(max-width:560px){.ct-offices{grid-template-columns:1fr;gap:16px}}
/* contact page layout */
.cx-grid{display:grid;grid-template-columns:1fr 1.05fr;gap:60px;align-items:start}
@media(max-width:900px){.cx-grid{grid-template-columns:1fr;gap:40px}}
.cx-lines{display:grid;gap:1px;background:var(--line);border:1px solid var(--line);margin-top:8px}
.cx-lines a,.cx-lines div.li{background:#fff;display:flex;align-items:center;gap:16px;padding:20px 22px;font-size:1.04rem;color:var(--navy);font-family:var(--disp);font-weight:500}
.cx-lines a:hover{background:var(--blue-050)}
.cx-lines .ic{width:20px;height:20px;color:var(--blue);stroke-width:1.9}
/* footer offices col */
.foffices{list-style:none;margin:0;padding:0;display:grid;gap:16px}
.foffices li{font-family:var(--f);font-size:.92rem;color:rgba(255,255,255,.58);line-height:1.55}
.foffices b{display:block;color:#fff;font-family:var(--disp);font-weight:500;text-transform:uppercase;font-size:1rem;letter-spacing:.02em;margin-bottom:3px}
.foot-top{grid-template-columns:1.5fr 1fr 1fr 1.25fr}
@media(max-width:900px){.foot-top{grid-template-columns:1fr 1fr}}
@media(max-width:560px){.foot-top{grid-template-columns:1fr}}
.nav-links a.active::after{width:100%}
/* thank you */
.ty{min-height:52vh;display:flex;align-items:center;text-align:center;background:var(--mist)}
.ty .wrap{max-width:720px}
.ty .tick{width:96px;height:96px;border-radius:50%;background:var(--blue-050);color:var(--blue);display:grid;place-items:center;margin:0 auto 28px}
.ty .tick .ic{width:46px;height:46px;stroke-width:2.4}
.ty h1{color:var(--ink);font-size:clamp(2.4rem,5vw,3.6rem)}
.ty p{font-size:1.12rem;margin:20px 0 8px}
.ty .tyb{display:flex;gap:14px;justify-content:center;flex-wrap:wrap;margin-top:30px}

/* ===== LEGAL PAGES ===== */
.page-hero-plain{min-height:clamp(320px,42vh,440px);background:var(--navy-3)}
.page-hero-plain::before{content:"";position:absolute;inset:0;background:repeating-linear-gradient(45deg,rgba(255,255,255,.03) 0 16px,transparent 16px 32px)}
.legal{max-width:860px;margin:0 auto}
.legal .lupdated{font-family:var(--f);font-size:.78rem;color:var(--muted);letter-spacing:.12em;text-transform:uppercase;font-weight:700;margin-bottom:30px;padding-bottom:22px;border-bottom:1px solid var(--line)}
.legal .lintro{font-size:1.14rem;color:var(--ink);font-family:var(--f);line-height:1.7;margin-bottom:14px}
.legal h2{font-size:clamp(1.35rem,2.6vw,1.85rem);margin:42px 0 14px;line-height:1.15;text-transform:none;letter-spacing:0}
.legal h2 .n{color:var(--gold);margin-right:12px}
.legal h3{font-size:1.12rem;margin:24px 0 8px;color:var(--ink);text-transform:none;letter-spacing:0;font-family:var(--f);font-weight:700}
.legal p{font-family:var(--f);font-size:1.03rem;color:var(--body);margin-bottom:14px;line-height:1.78}
.legal ul{margin:6px 0 18px;padding:0;list-style:none;display:grid;gap:10px}
.legal ul li{position:relative;padding-left:26px;font-family:var(--f);font-size:1.03rem;color:var(--body);line-height:1.7}
.legal ul li::before{content:"";position:absolute;left:2px;top:11px;width:8px;height:8px;background:var(--gold);transform:rotate(45deg)}
.legal a{color:var(--blue);font-weight:600}
.legal a:hover{color:var(--gold)}
.legal strong{color:var(--ink)}
.legal .lbox{background:var(--mist);border-left:3px solid var(--gold);padding:22px 26px;margin:20px 0 0;font-family:var(--f);font-size:1rem;color:var(--ink);line-height:1.9}
.page-hero-plain.nohdr{min-height:clamp(230px,30vh,320px)}
.page-hero-plain.nohdr .wrap{padding:60px 0 46px}
